import{_ as a,o as d,c as t,a3 as o}from"./chunks/framework.cNy3aYYk.js";const m=JSON.parse('{"title":"Tenant API v1 — Calendar","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Tenant API v1 — Calendar | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/api/tenant-v1-calendar"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Tenant API v1 — Calendar | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/api/tenant-v1-calendar"}]]},"headers":[],"relativePath":"api/tenant-v1-calendar.md","filePath":"api/tenant-v1-calendar.md","lastUpdated":1791493424000}'),c={name:"api/tenant-v1-calendar.md"};function n(r,e,s,l,i,h){return d(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="tenant-api-v1-—-calendar" tabindex="-1">Tenant API v1 — Calendar <a class="header-anchor" href="#tenant-api-v1-—-calendar" aria-label="Permalink to &quot;Tenant API v1 — Calendar&quot;">​</a></h1><p>Base path: <code>/api/tenant/v1</code></p><p>Middleware: <code>auth:tenant-api</code>, <code>tenant.user</code>, <code>verified</code>, <code>module:calendar</code>, plus <code>can:calendar.*</code> / policies.</p><p>Visibility: without <code>calendar.view_all</code>, events where <code>organizer_id</code> is the current user, <strong>or</strong> meeting projections where the actor is on <code>meeting_attendees.user_id</code>, <strong>or</strong> manual events shared via <code>calendar_event_shares</code>, <strong>or</strong> events on a <strong>named calendar</strong> the actor may see (creator, linked department members when Departments is entitled, or <code>calendar.view_all</code> / <code>calendar.manage_calendars</code>). Invitees and <strong>viewer</strong> shares receive <code>read_only: true</code> and cannot update/cancel/delete. <strong>Editor</strong> shares may mutate manual events when they also have Spatie <code>calendar.update</code> / <code>delete</code>. <code>organizer_id</code> and <code>assignee_id</code> are prohibited on write payloads; optional <code>calendar_id</code> selects a named calendar (<code>null</code> / omitted = personal).</p><h2 id="upcoming" tabindex="-1">Upcoming <a class="header-anchor" href="#upcoming" aria-label="Permalink to &quot;Upcoming&quot;">​</a></h2><h3 id="get-calendar-upcoming" tabindex="-1">GET <code>/calendar/upcoming</code> <a class="header-anchor" href="#get-calendar-upcoming" aria-label="Permalink to &quot;GET `/calendar/upcoming`&quot;">​</a></h3><p>Query: <code>limit</code> (1–25, default 8). Scheduled events with <code>starts_at &gt;= now()</code>, visibility-scoped.</p><h2 id="events" tabindex="-1">Events <a class="header-anchor" href="#events" aria-label="Permalink to &quot;Events&quot;">​</a></h2><h3 id="get-calendar-events" tabindex="-1">GET <code>/calendar/events</code> <a class="header-anchor" href="#get-calendar-events" aria-label="Permalink to &quot;GET `/calendar/events`&quot;">​</a></h3><p>Query: <code>search</code>, <code>status</code>, <code>from</code>, <code>to</code>, <code>trashed</code>, <code>sort</code> (default <code>starts_at</code>), <code>direction</code> (default <code>asc</code>), <code>page</code>, <code>per_page</code>, <code>paginate</code> (<code>0</code>/<code>false</code> returns a non-paginated range collection when <code>from</code>+<code>to</code> are set), <code>calendar_id</code> (<code>personal</code> or a named calendar id — <strong>1.9.0</strong>).</p><p>Events may have <code>source</code> <code>manual</code> | <code>meeting</code> | <code>project</code> | <code>task</code> | <code>lead</code> | <code>contact</code> | <code>company</code> | <code>external</code> (sourced overlays are read on the grid; mutate via the parent module; External is view-only). Responses include <code>read_only</code> (boolean) for SPA gating, nullable <code>calendar_id</code> / nested <code>calendar</code> when on a named calendar (<strong>1.9.0</strong>), and nullable <code>external_provider</code> (<code>google</code>|<code>microsoft</code>) / <code>external_event_id</code> when mapped to a Calendar sync provider (<strong>1.4.0</strong>).</p><h3 id="post-calendar-events" tabindex="-1">POST <code>/calendar/events</code> <a class="header-anchor" href="#post-calendar-events" aria-label="Permalink to &quot;POST `/calendar/events`&quot;">​</a></h3><p>Body: <code>title</code> (required), <code>description</code>, <code>starts_at</code>, <code>ends_at</code> (<code>after_or_equal:starts_at</code>), <code>all_day</code>, <code>timezone</code>, <code>color</code>, optional <code>calendar_id</code> (named calendar the actor may post to; omit/<code>null</code> = personal).</p><p>Sets <code>organizer_id</code> to the authenticated user. Status <code>scheduled</code>, source <code>manual</code>. Posting to a named calendar requires <code>calendar.create</code> and membership (or manage override).</p><h3 id="get-calendar-events-id" tabindex="-1">GET <code>/calendar/events/{id}</code> <a class="header-anchor" href="#get-calendar-events-id" aria-label="Permalink to &quot;GET `/calendar/events/{id}`&quot;">​</a></h3><h3 id="put-calendar-events-id" tabindex="-1">PUT <code>/calendar/events/{id}</code> <a class="header-anchor" href="#put-calendar-events-id" aria-label="Permalink to &quot;PUT `/calendar/events/{id}`&quot;">​</a></h3><p>Same writable fields as create (partial). Organizer/source/status fields prohibited.</p><p>Used by the SPA form and by Week/Day <strong>drag-and-drop</strong> reschedule (<code>starts_at</code> + <code>ends_at</code> only).</p><h3 id="post-calendar-events-id-cancel" tabindex="-1">POST <code>/calendar/events/{id}/cancel</code> <a class="header-anchor" href="#post-calendar-events-id-cancel" aria-label="Permalink to &quot;POST `/calendar/events/{id}/cancel`&quot;">​</a></h3><p>Sets <code>status=cancelled</code> and <code>cancelled_at</code>.</p><h3 id="delete-calendar-events-id" tabindex="-1">DELETE <code>/calendar/events/{id}</code> <a class="header-anchor" href="#delete-calendar-events-id" aria-label="Permalink to &quot;DELETE `/calendar/events/{id}`&quot;">​</a></h3><p>Soft delete.</p><h2 id="shares-manual-events" tabindex="-1">Shares (manual events) <a class="header-anchor" href="#shares-manual-events" aria-label="Permalink to &quot;Shares (manual events)&quot;">​</a></h2><p>Organizer or <code>calendar.view_all</code> may manage shares.</p><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Notes</th></tr></thead><tbody><tr><td>GET</td><td><code>/calendar/events/{id}/shares</code></td><td>List shares</td></tr><tr><td>POST</td><td><code>/calendar/events/{id}/shares</code></td><td>Body: <code>user_id</code>, <code>access</code> (<code>viewer</code>|<code>editor</code>)</td></tr><tr><td>PUT</td><td><code>/calendar/events/{id}/shares/{share}</code></td><td>Body: <code>access</code></td></tr><tr><td>DELETE</td><td><code>/calendar/events/{id}/shares/{share}</code></td><td>Remove share</td></tr></tbody></table><h2 id="named-calendars-1-9-0" tabindex="-1">Named calendars (1.9.0) <a class="header-anchor" href="#named-calendars-1-9-0" aria-label="Permalink to &quot;Named calendars (1.9.0)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Notes</th></tr></thead><tbody><tr><td>GET</td><td><code>/calendar/calendars</code></td><td>List named calendars visible to the actor (<code>can:calendar.view</code>)</td></tr><tr><td>POST</td><td><code>/calendar/calendars</code></td><td>Create — body <code>name</code> (required), optional <code>department_id</code> when Departments entitled (<code>can:calendar.manage_calendars</code>)</td></tr><tr><td>PUT</td><td><code>/calendar/calendars/{calendar}</code></td><td>Update name / department</td></tr><tr><td>DELETE</td><td><code>/calendar/calendars/{calendar}</code></td><td>Soft-delete</td></tr></tbody></table><h2 id="integrations-google-outlook-sync-—-1-4-0" tabindex="-1">Integrations (Google / Outlook sync — 1.4.0+) <a class="header-anchor" href="#integrations-google-outlook-sync-—-1-4-0" aria-label="Permalink to &quot;Integrations (Google / Outlook sync — 1.4.0+)&quot;">​</a></h2><p>Requires <code>calendar.manage_integrations</code>. Per-user connections; push covers manual + Meeting/Task/Lead (<strong>1.5.0</strong>) + Project/Contact/Company overlays (<strong>1.7.0</strong>). Inbound pull (<strong>1.6.0</strong>) + webhook watches (<strong>1.8.0</strong>) — see <a href="/developer-guide/calendar">developer guide</a>.</p><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Notes</th></tr></thead><tbody><tr><td>GET</td><td><code>/calendar/integrations</code></td><td>Status per provider (<code>google</code>, <code>microsoft</code>): <code>connected</code>, <code>status</code>, <code>external_calendar_id</code>, <code>connected_at</code>, watch meta when active</td></tr><tr><td>GET</td><td><code>/calendar/integrations/{provider}/authorize</code></td><td>OAuth authorize URL; 422 if platform credentials unset</td></tr><tr><td>POST</td><td><code>/calendar/integrations/sync</code></td><td>Sync now — pulls provider window + ensures watch</td></tr><tr><td>DELETE</td><td><code>/calendar/integrations/{provider}</code></td><td>Disconnect; stops watch/push/pull (provider copies remain)</td></tr></tbody></table><p>OAuth callback (platform): <code>GET /api/oauth/calendar-sync/{provider}/callback</code> → <code>{FRONTEND_URL}/#/calendar?integrations={status}</code>.</p><p>Public webhooks (platform): <code>POST /webhooks/calendar-sync/{provider}</code> — Google channel headers / Microsoft Graph <code>validationToken</code> + <code>clientState</code> (<strong>1.8.0</strong>).</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p><code>calendar.view</code> · <code>create</code> · <code>update</code> · <code>delete</code> · <code>view_all</code> · <code>manage_integrations</code> · <code>manage_calendars</code></p>',34)])])}const u=a(c,[["render",n]]);export{m as __pageData,u as default};
